//! Source-derived TD/RA template type to theater ICON-set metadata.
//!
//! IDs, theater masks, and ICON-set filename stems are derived from EA:
//! - CnC_Tiberian_Dawn/DEFINES.H and CDATA.CPP
//! - CnC_Red_Alert/CODE/DEFINES.H and CODE/CDATA.CPP
//!
//! The optional RA FIXIT_ANTS TEMPLATE_HILL01 entry is omitted because it is
//! compiled only when that non-default feature macro is enabled.

use crate::map::GameVariant;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum TemplateTheater { Desert, Jungle, Temperate, Winter, Snow, Interior }

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TemplateAssetMetadata {
    pub type_id: u16,
    pub symbolic_name: &'static str,
    /// Basename without theater suffix or extension.
    pub asset_stem: &'static str,
    /// Bit positions match the selected game's upstream TheaterType enum.
    pub theater_mask: u8,
}

impl TemplateAssetMetadata {
    pub const fn supports(self, variant: GameVariant, theater: TemplateTheater) -> bool {
        let bit = match (variant, theater) {
            (GameVariant::TiberianDawn, TemplateTheater::Desert) => 1 << 0,
            (GameVariant::TiberianDawn, TemplateTheater::Jungle) => 1 << 1,
            (GameVariant::TiberianDawn, TemplateTheater::Temperate) => 1 << 2,
            (GameVariant::TiberianDawn, TemplateTheater::Winter) => 1 << 3,
            (GameVariant::RedAlert, TemplateTheater::Temperate) => 1 << 0,
            (GameVariant::RedAlert, TemplateTheater::Snow) => 1 << 1,
            (GameVariant::RedAlert, TemplateTheater::Interior) => 1 << 2,
            _ => 0,
        };
        self.theater_mask & bit != 0
    }
}

