pub fn template_asset_metadata(variant: GameVariant, type_id: u16) -> Option<&'static TemplateAssetMetadata> {
    let entries = match variant {
        GameVariant::TiberianDawn => TD_TEMPLATE_ASSETS,
        GameVariant::RedAlert => RA_TEMPLATE_ASSETS,
    };
    entries.binary_search_by_key(&type_id, |entry| entry.type_id).ok().map(|index| &entries[index])
}

pub fn template_asset_for_theater(
    variant: GameVariant, type_id: u16, theater: TemplateTheater,
) -> Option<&'static TemplateAssetMetadata> {
    template_asset_metadata(variant, type_id).filter(|entry| entry.supports(variant, theater))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn catalogs_are_sorted_and_ids_match_source_metadata() {
        for entries in [TD_TEMPLATE_ASSETS, RA_TEMPLATE_ASSETS] {
            assert!(entries.windows(2).all(|pair| pair[0].type_id < pair[1].type_id));
        }
        let td_clear = template_asset_metadata(GameVariant::TiberianDawn, 0).unwrap();
        assert_eq!(td_clear.symbolic_name, "TEMPLATE_CLEAR1");
        assert_eq!(td_clear.asset_stem, "CLEAR1");
        assert!(td_clear.supports(GameVariant::TiberianDawn, TemplateTheater::Jungle));
        let ra_shore = template_asset_metadata(GameVariant::RedAlert, 3).unwrap();
        assert_eq!(ra_shore.symbolic_name, "TEMPLATE_SHORE01");
        assert_eq!(ra_shore.asset_stem, "SH01");
        assert!(ra_shore.supports(GameVariant::RedAlert, TemplateTheater::Temperate));
        assert!(ra_shore.supports(GameVariant::RedAlert, TemplateTheater::Snow));
        assert!(!ra_shore.supports(GameVariant::RedAlert, TemplateTheater::Interior));
    }

    #[test]
    fn rejects_cross_variant_theaters() {
        let td_clear = template_asset_metadata(GameVariant::TiberianDawn, 0).unwrap();
        assert!(!td_clear.supports(GameVariant::TiberianDawn, TemplateTheater::Snow));
        assert!(template_asset_for_theater(GameVariant::RedAlert, 0, TemplateTheater::Interior).is_some());
    }

    #[test]
    fn known_template_ids_resolve_to_source_asset_stems() {
        assert_eq!(template_asset_for_theater(GameVariant::TiberianDawn, 1, TemplateTheater::Desert).unwrap().asset_stem, "W1");
        assert_eq!(template_asset_for_theater(GameVariant::RedAlert, 1, TemplateTheater::Temperate).unwrap().asset_stem, "W1");
    }
}
